from copy import deepcopy

def rotate90(grid):
    """Return a new grid rotated 90 degrees clockwise."""
    return [list(row) for row in zip(*grid[::-1])]

def all_rotations(grid):
    """Yield the grid after 0, 90, 180, and 270-degree rotations."""
    yield deepcopy(grid)
    yield rotate90(grid)
    yield rotate90(rotate90(grid))
    yield rotate90(rotate90(rotate90(grid)))

def equal_under_rotation(grid1, grid2):
    """Return True if grid2 equals any rotation of grid1."""
    if not grid1 and not grid2:
        return True
    if len(grid1) != len(grid2) or len(grid1[0]) != len(grid2[0]):
        return False
    return any(equal_pairwise(g1, g2) for g1, g2 in zip(all_rotations(grid1), [grid2] * 4))

def equal_pairwise(g1, g2):
    """Test two grids for exact equality of every value."""
    for row1, row2 in zip(g1, g2):
        for x, y in zip(row1, row2):
            if x != y:
                return False
    return True
```

